function.arguments:
{"command": "cat > /tmp/show.py <<'PYEOF'
import sys, re
data = sys.stdin.buffer.read().decode('utf-8','replace')
colors={'30':'black','31':'red','32':'green','33':'yellow','34':'blue','35':'magenta','36':'cyan','37':'white'}
bcolors={'90':'BLACK','91':'RED','92':'GREEN','93':'YELLOW','94':'BLUE','95':'MAGENTA','96':'CYAN','97':'WHITE'}
bgs={'40':'black','41':'red','42':'green','43':'yellow','44':'blue','45':'magenta','46':'cyan','47':'white'}
bbgs={'100':'BLACK','101':'RED','102':'GREEN','103':'YELLOW','104':'BLUE','105':'MAGENTA','106':'CYAN','107':'WHITE'}
attrs={'1':'bold','2':'dim','3':'italic','4':'underline','5':'blink','6':'blink2','7':'reverse','8':'hidden','9':'strike','21':'double-underline','22':'/dim','23':'/italic','24':'/underline','25':'/blink','27':'/reverse','29':'/strike','39':'/fg','49':'/bg'}
def repl(m):
    s=m.group(0)
    if s=='\x1b[0m': return '{/}'
    body=s[2:-1]
    if body=='': return '{/}'
    parts=body.split(';')
    lbl=[]
    for p in parts:
        if p in colors: lbl.append(colors[p])
        elif p in bcolors: lbl.append(bcolors[p].lower())
        elif p in bgs: lbl.append('bg'+bgs[p])
        elif p in bbgs: lbl.append('bg'+bbgs[p].lower())
        elif p in attrs: lbl.append(attrs[p])
        elif p.startswith('38'): lbl.append('extfg'+p)
        elif p.startswith('48'): lbl.append('extbg'+p)
        else: lbl.append('?'+p)
    return '{'+';'.join(lbl)+'}'
data=re.sub(r'\x1b\[[0-9;]*m', repl, data)
sys.stdout.write(data)
PYEOF
cd /tmp/pr && /workspace/executable -p --config-path c9.toml dates.txt 2>&1 | head -12 | python3 /tmp/show.py"}

