{"command": "cd /workspace && cat > src/theme.rs <<'EOF'
//! The theme: colors, styles and the TOML configuration.
use std::path::Path;

use serde::Deserialize;

/// The ANSI colors supported by the theme file.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Color {
    Default,
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    White,
    BrightBlack,
    BrightRed,
    BrightGreen,
    BrightYellow,
    BrightBlue,
    BrightMagenta,
    BrightCyan,
    BrightWhite,
}

impl Color {
    /// The index in the ordering used when sorting custom keyword styles.
    pub fn order(self) -> u8 {
        match self {
            Color::Default => 0,
            Color::Black => 1,
            Color::Red => 2,
            Color::Green => 3,
            Color::Yellow => 4,
            Color::Blue => 5,
            Color::Magenta => 6,
            Color::Cyan => 7,
            Color::White => 8,
            Color::BrightBlack => 9,
            Color::BrightRed => 10,
            Color::BrightGreen => 11,
            Color::BrightYellow => 12,
            Color::BrightBlue => 13,
            Color::BrightMagenta => 14,
            Color::BrightCyan => 15,
            Color::BrightWhite => 16,
        }
    }

    /// ANSI code used for the foreground color.
    pub fn fg_code(self) -> u8 {
        match self {
            Color::Default => 39,
            Color::Black => 30,
            Color::Red => 31,
            Color::Green => 32,
            Color::Yellow => 33,
            Color::Blue => 34,
            Color::Magenta => 35,
            Color::Cyan => 36,
            Color::White => 37,
            Color::BrightBlack => 90,
            Color::BrightRed => 91,
            Color::BrightGreen => 92,
            Color::BrightYellow => 93,
            Color::BrightBlue => 94,
            Color::BrightMagenta => 95,
            Color::BrightCyan => 96,
            Color::BrightWhite => 97,
        }
    }

    /// ANSI code used for the background color.
    pub fn bg_code(self) -> u8 {
        match self {
            Color::Default => 49,
            Color::Black => 40,
            Color::Red => 41,
            Color::Green => 42,
            Color::Yellow => 43,
            Color::Blue => 44,
            Color::Magenta => 45,
            Color::Cyan => 46,
            Color::White => 47,
            Color::BrightBlack => 100,
            Color::BrightRed => 101,
            Color::BrightGreen => 102,
            Color::BrightYellow => 103,
            Color::BrightBlue => 104,
            Color::BrightMagenta => 105,
            Color::BrightCyan => 106,
            Color::BrightWhite => 107,
        }
    }
}

/// A text style.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, PartialOrd, Ord, Deserialize)]
pub struct Style {
    pub fg: Option<Color>,
    pub faint: bool,
    pub underline: bool,
    pub italic: bool,
    pub bold: bool,
    pub bg: Option<Color>,
}

impl Style {
    /// Build a style with only a foreground color set.
    pub fn fg(color: Color) -> Self {
        Style {
            fg: Some(color),
            ..Default::default()
        }
    }

    /// Build a style with only a background color set.
    pub fn bg(color: Color) -> Self {
        Style {
            bg: Some(color),
            ..Default::default()
        }
    }

    /// The ANSI escape sequence activating this style (empty when plain).
    pub fn to_start(&self) -> String {
        let mut codes: Vec<String> = Vec::new();
        if self.bold {
            codes.push("1".to_string());
        }
        if self.faint {
            codes.push("2".to_string());
        }
        if self.italic {
            codes.push("3".to_string());
        }
        if self.underline {
            codes.push("4".to_string());
        }
        if let Some(bg) = self.bg {
            codes.push(bg.bg_code().to_string());
        }
        if let Some(fg) = self.fg {
            codes.push(fg.fg_code().to_string());
        }
        if codes.is_empty() {
            String::new()
        } else {
            format!("\x1b[{}m", codes.join(";"))
        }
    }

    /// True when the style would not produce any escape sequence.
    pub fn is_plain(&self) -> bool {
        self.to_start().is_empty()
    }
}

/// The reset sequence used after a styled piece of text.
pub const RESET: &str = "\x1b[0m";

#[derive(Debug, Default, Deserialize)]
pub struct DateToml {
    pub date: Option<Style>,
    pub time: Option<Style>,
    pub separator: Option<Style>,
}

#[derive(Debug, Default, Deserialize)]
pub struct NumberToml {
    pub number: Option<Style>,
}

#[derive(Debug, Default, Deserialize)]
pub struct UrlToml {
    pub http: Option<Style>,
    pub https: Option<Style>,
    pub host: Option<Style>,
    pub path: Option<Style>,
}

#[derive(Debug, Default, Deserialize)]
pub struct PointerToml {
    pub number: Option<Style>,
    pub letter: Option<Style>,
    pub separator: Option<Style>,
}

#[derive(Debug, Default, Deserialize)]
pub struct PathToml {
    pub segment: Option<Style>,
    pub separator: Option<Style>,
}

#[derive(Debug, Default, Deserialize)]
pub struct QuotesToml {
    pub style: Option<Style>,
}

#[derive(Debug, Default, Deserialize)]
pub struct UuidToml {
    pub number: Option<Style>,
    pub letter: Option<Style>,
    pub separator: Option<Style>,
}

#[derive(Debug, Default, Deserialize)]
pub struct UnixProcessToml {
    pub name: Option<Style>,
    pub id: Option<Style>,
    pub bracket: Option<Style>,
}

#[derive(Debug, Default, Deserialize)]
pub struct JsonToml {
    pub key: Option<Style>,
}

#[derive(Debug, Default, Deserialize)]
pub struct KeyValueToml {
    pub key: Option<Style>,
    pub separator: Option<Style>,
}

#[derive(Debug, Default, Deserialize)]
pub struct KeywordToml {
    pub words: Vec<String>,
    pub style: Style,
}

/// The complete theme, as read from the TOML configuration file.
#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Theme {
    pub dates: Option<DateToml>,
    pub numbers: Option<NumberToml>,
    pub urls: Option<UrlToml>,
    pub pointers: Option<PointerToml>,
    pub paths: Option<PathToml>,
    pub quotes: Option<QuotesToml>,
    pub uuids: Option<UuidToml>,
    pub processes: Option<UnixProcessToml>,
    pub json: Option<JsonToml>,
    pub key_value_pairs: Option<KeyValueToml>,
    pub keywords: Option<Vec<KeywordToml>>,
}

impl Theme {
    /// The hard coded theme that is used when no configuration file is found.
    pub fn default_theme() -> Theme {
        Theme {
            dates: Some(DateToml {
                date: Some(Style::fg(Color::Magenta)),
                time: Some(Style::fg(Color::Blue)),
                separator: Some(Style {
                    faint: true,
                    ..Default::default()
                }),
            }),
            numbers: Some(NumberToml {
                number: Some(Style::fg(Color::Cyan)),
            }),
