pub type Result<T> = std::result::Result<T, TspinError>;

/// All the errors that can be produced by tspin.
#[derive(Debug)]
pub enum TspinError {
    /// The file that was provided cannot be highlighted.
    IoError(String, std::io::Error),
    /// The path is not a file.
    NotAFile,
    /// Could not open the file.
    OpenError(String, std::io::Error),
