    PagerSpawn(String, std::io::Error),
    /// Could not read from the command.
    CommandRead(String, std::io::Error),
}

impl std::fmt::Display for TspinError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            TspinError::IoError(path, e) => write!(f, "{}: {}", path, crate_error_text(e)),
            TspinError::NotAFile => write!(f, "Path is not a file"),
            TspinError::OpenError(path, e) => write!(f, "Could not open file: {:?}: {}", path, crate_error_text(e)),
            TspinError::TomlNotFound => write!(f, "could not find the TOML file"),
            TspinError::TomlRead(msg, e) => write!(f, "could not read the TOML file: {}: {}", msg, crate_error_text(e)),
            TspinError::TomlParse(msg) => write!(f, "{}", msg),
            TspinError::BothEnableAndDisable => write!(f, "cannot both enable and disable highlighters"),
            TspinError::HomeEnvironment(msg) => write!(f, "could not determine the home environment: {}", msg),
            TspinError::PagerParse => write!(f, "Could not parse custom pager command"),
            TspinError::PagerSpawn(msg, e) => write!(f, "Could not run pager: {}: {}", msg, crate_error_text(e)),
            TspinError::CommandRead(msg, e) => write!(f, "Could not read from command: {}: {}", msg, crate_error_text(e)),
        }
    }
}

/// The io error text as produced by the standard library.
pub fn crate_error_text(e: &std::io::Error) -> String {
    e.to_string()
}

impl TspinError {
    /// The error kind that is printed on the first line (empty when unknown).
    pub fn kind(&self) -> &'static str {
        match self {
            TspinError::PagerSpawn(..) => "less::command_spawn",
            _ => "",
        }
    }

    /// The message that is printed next to the cross.
    pub fn message(&self) -> String {
        match self {
            TspinError::IoError(path, e) => format!("{}: {}", path, crate_error_text(e)),
            TspinError::NotAFile => "Path is not a file".to_string(),
            TspinError::OpenError(path, e) => format!("Could not open file: {:?}: {}", path, crate_error_text(e)),
            TspinError::TomlNotFound => "could not find the TOML file".to_string(),
            TspinError::TomlRead(msg, e) => format!("could not read the TOML file: {}: {}", msg, crate_error_text(e)),
            TspinError::TomlParse(msg) => msg.clone(),
            TspinError::BothEnableAndDisable => "cannot both enable and disable highlighters".to_string(),
            TspinError::HomeEnvironment(msg) => format!("could not determine the home environment: {}", msg),
            TspinError::PagerParse => "Could not parse custom pager command".to_string(),
            TspinError::PagerSpawn(msg, e) => format!("Could not run pager: {}: {}", msg, crate_error_text(e)),
            TspinError::CommandRead(msg, e) => format!("Could not read from command: {}: {}", msg, crate_error_text(e)),
        }
    }

    /// The causes that are printed below the message.
    pub fn causes(&self) -> Vec<String> {
        match self {
            TspinError::OpenError(_, e) => vec![crate_error_text(e)],
            TspinError::TomlRead(_, e) => vec![crate_error_text(e)],
            TspinError::PagerSpawn(_, e) => vec![crate_error_text(e)],
            TspinError::CommandRead(_, e) => vec![crate_error_text(e)],
            TspinError::HomeEnvironment(_) => vec!["environment variable not found".to_string()],
            _ => vec![],
        }
    }
}

/// Print the error to stderr the way tspin does.
pub fn print_error(err: &TspinError) {
    let kind = err.kind();
    if kind.is_empty() {
        eprintln!("Error:  {}", crate_warn(err));
    } else {
        eprintln!("Error: {}\n", kind);
        eprintln!("  × {}", err.message());
    }
    for cause in err.causes() {
        eprintln!("  ╰─▶ {}", cause);
    }
    eprintln!();
}

/// The message with the warning glyph and the path highlighted in yellow.
fn crate_warn(err: &TspinError) -> String {
    match err {
        TspinError::IoError(path, _) => format!("⚠ \x1b[33m{}\x1b[0m: {}", path, err.message()),
        other => format!("× {}", other.message()),
    }
}
EOF
