/// The regex for a time part (HH:MM:SS with an optional fraction).
const TIME: &str = r"([01]?\d|2[0-3]):([0-5]\d):([0-5]\d)([.,:]\d+)?";

/// Class of characters that are valid in an url path.
const URL_PATH_CHARS: &str = r"[0-9A-Za-z._~+%/-]";
/// Class of characters that are valid in an url query key or value.
const URL_QUERY_CHARS: &str = r"[0-9A-Za-z._~+%+-]";
/// Class of characters that are valid in a path segment.
const SEGMENT_CHARS: &str = r"[0-9A-Za-z._-]";

/// Styles that cannot be configured through the theme file.
#[derive(Clone)]
pub struct Builtin {
    pub date_fill: Style,
    pub tz: Style,
    pub hex_number: Style,
    pub hex_letter: Style,
    pub hex_separator: Style,
    pub pointer_prefix: Style,
    pub url_query_separator: Style,
    pub url_query_name: Style,
    pub url_query_value: Style,
    pub json_structural: Style,
}

impl Builtin {
    pub fn new() -> Builtin {
        Builtin {
            date_fill: Style::fg(Color::Red),
            tz: Style::fg(Color::Red),
            hex_number: Style {
                italic: true,
                fg: Some(Color::Blue),
                ..Default::default()
            },
            hex_letter: Style {
                italic: true,
                fg: Some(Color::Magenta),
                ..Default::default()
            },
            hex_separator: Style::fg(Color::Red),
            pointer_prefix: Style::fg(Color::Red),
            url_query_separator: Style::fg(Color::Red),
            url_query_name: Style::fg(Color::Magenta),
            url_query_value: Style::fg(Color::Cyan),
            json_structural: Style {
                faint: true,
                ..Default::default()
            },
        }
    }
}

/// Split `text` into spans of digits and separators. Characters that are
/// neither are pushed as unstyled text.
fn push_digit_sep(out: &mut Vec<Piece>, text: &str, digit: &Style, sep: &Style, sep_chars: &str) {
    let bytes = text.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let start = i;
        if bytes[i].is_ascii_digit() {
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                i += 1;
            }
            out.push(Piece::styled(&text[start..i], digit.clone()));
        } else if sep_chars.as_bytes().contains(&bytes[i]) {
            i += 1;
            out.push(Piece::styled(&text[start..i], sep.clone()));
        } else {
            i += 1;
            out.push(Piece::unstyled(&text[start..i]));
        }
    }
}

fn push_color(out: &mut Vec<Piece>, text: &str, style: &Style) {
    if !text.is_empty() {
        out.push(Piece::styled(text, style.clone()));
    }
}

fn push_plain(out: &mut Vec<Piece>, text: &str) {
    if !text.is_empty() {
        out.push(Piece::unstyled(text));
    }
}

/// Build the json highlighter, which rewrites the whole line when it parses.
fn json_highlighter(theme: &Theme, builtin: &Builtin) -> Highlighter {
    let key_style = theme.json_key_style();
    let structural = builtin.json_structural.clone();
    let run: HighlighterFn = Box::new(move |text: &str| {
        let value: Value = match serde_json::from_str(text) {
            Ok(v) => v,
            Err(_) => return None,
        };
        let mut out = Vec::new();
        render_json(&value, &mut out, &key_style, &structural);
        Some(out)
    });
    Highlighter { run }
}

fn render_json(value: &Value, out: &mut Vec<Piece>, key: &Style, structural: &Style) {
    match value {
        Value::Object(map) => {
            push_color(out, "{", structural);
            let mut first = true;
            for (k, v) in map {
                if !first {
                    push_color(out, ",", structural);
                }
                first = false;
                push_plain(out, " ");
                push_color(out, "\"", structural);
                push_color(out, k, key);
                push_color(out, "\"", structural);
                push_color(out, ":", structural);
                push_plain(out, " ");
                render_json(v, out, key, structural);
            }
            push_plain(out, " ");
            push_color(out, "}", structural);
        }
        Value::Array(items) => {
            push_color(out, "[", structural);
            let mut first = true;
            for v in items {
                if !first {
                    push_color(out, ",", structural);
                    push_plain(out, " ");
                }
                first = false;
                render_json(v, out, key, structural);
            }
            push_color(out, "]", structural);
        }
        Value::String(s) => {
            push_color(out, "\"", structural);
            push_plain(out, s);
            push_color(out, "\"", structural);
        }
        other => push_plain(out, &other.to_string()),
    }
}

/// Build the date highlighter, matching datetimes, dates and times.
fn date_highlighter(theme: &Theme, builtin: &Builtin) -> Highlighter {
    let date_style = theme.date_style();
    let time_style = theme.time_style();
    let sep_style = theme.date_separator_style();
    let fill = builtin.date_fill.clone();
    let tz = builtin.tz.clone();

    let datetime_re = Regex::new(&format!(
        r"(?P<date>{})[ \tT](?P<time>{})Z?",
        DATE, TIME
    ))
    .unwrap();
    let date_re = Regex::new(&format!(r"(?P<date>{})", DATE)).unwrap();
    let time_re = Regex::new(&format!(r"(?P<time>{})Z?", TIME)).unwrap();

    let run: HighlighterFn = Box::new(move |text: &str| {
        for re in [&datetime_re, &date_re, &time_re] {
            let mut out: Vec<Piece> = Vec::new();
            let mut last = 0;
            let mut matched = false;
            for caps in re.captures_iter(text) {
                matched = true;
                let start = caps.get(0).unwrap().start();
                let end = caps.get(0).unwrap().end();
                push_plain(&mut out, &text[last..start]);
                if let (Some(d), Some(t)) = (caps.name("date"), caps.name("time")) {
                    push_digit_sep(&mut out, d.as_str(), &date_style, &sep_style, "-/.");
                    push_color(&mut out, &text[d.end()..t.start()], &fill);
                    push_digit_sep(&mut out, t.as_str(), &time_style, &sep_style, "-/.,:");
                    if let Some(m) = caps.get(caps.len() - 1) {
                        if m.as_str() == "Z" && m.end() == end {
                            push_color(&mut out, "Z", &tz);
                        }
                    }
                } else if let Some(d) = caps.name("date") {
                    push_digit_sep(&mut out, d.as_str(), &date_style, &sep_style, "-/.");
                } else if let Some(t) = caps.name("time") {
                    push_digit_sep(&mut out, t.as_str(), &time_style, &sep_style, "-/.,:");
                    if let Some(m) = caps.get(caps.len() - 1) {
                        if m.as_str() == "Z" && m.end() == end {
                            push_color(&mut out, "Z", &tz);
                        }
                    }
                }
                last = end;
            }
            if matched {
                push_plain(&mut out, &text[last..]);
                return Some(out);
            }
        }
        None
    });
    Highlighter { run }
}

/// Build the ip address highlighter, handling both ipv6 and ipv4.
fn ip_highlighter(theme: &Theme, builtin: &Builtin) -> Highlighter {
    let number = builtin.hex_number.clone();
    let letter = builtin.hex_letter.clone();
    let separator = builtin.hex_separator.clone();
    let ipv4_re = Regex::new(&format!(
        r"\b(?P<ip>(?:{}\.){3}{})(?P<cidr>/\d{{1,2}})?\b",
        r"(?:25[0-5]|2[0-4]\d|[01]?\d\d?)",
        r"(?:25[0-5]|2[0-4]\d|[01]?\d\d?)"
    ))
    .unwrap();

    let run: HighlighterFn = Box::new(move |text: &str| {
        let mut out: Vec<Piece> = Vec::new();
        let bytes = text.as_bytes();
        let mut last = 0;
        let mut i = 0;
        let mut matched = false;
        while i <= bytes.len() {
            // lookbehind: not preceded by a hex digit or colon
            if i > 0 && (bytes[i - 1].is_ascii_hexdigit() || bytes[i - 1] == b':') {
                i += 1;
                continue;
            }
            match find_ipv6(&bytes[i..]) {
                Some(len) => {
                    let end = i + len;
                    if end < bytes.len()
                        && (bytes[end].is_ascii_hexdigit()
                            || bytes[end] == b':'
                            || bytes[end] == b'.')
                    {
                        i += 1;
                        continue;
                    }
                    push_plain(&mut out, &text[last..i]);
                    for (s, e) in char_runs(&text[i..end], "0123456789", "abcdefABCDEF", ":.") {
                        push_plain_style(&mut out, &text[i + s..i + e], &number, &letter, &separator);
                    }
                    last = end;
                    matched = true;
                    i = end;
                }
                None => {
                    i += 1;
                }
            }
        }
        if matched {
            push_plain(&mut out, &text[last..]);
        } else {
            out.clear();
            let mut last = 0;
            let mut m = false;
            for caps in ipv4_re.captures_iter(text) {
                m = true;
                let start = caps.get(0).unwrap().start();
                let end = caps.get(0).unwrap().end();
                push_plain(&mut out, &text[last..start]);
                let ip = caps.name("ip").unwrap();
                for (s, e) in runs(ip.as_str(), |c| c.is_ascii_digit()) {
                    push_color(&mut out, &ip.as_str()[s..e], &number);
                    if e < ip.as_str().len() {
                        push_color(&mut out, ".", &separator);
                    }
                }
                if let Some(c) = caps.name("cidr") {
                    push_color(&mut out, "/", &separator);
                    for (s, e) in runs(&c.as_str()[1..], |c| c.is_ascii_digit()) {
                        push_color(&mut out, &c.as_str()[1..][s..e], &number);
                    }
                }
                last = end;
            }
            if m {
                push_plain(&mut out, &text[last..]);
                return Some(out);
            }
            return None;
        }
        if !out.is_empty() {
            return Some(out);
        }
        None
    });
    Highlighter { run }
}

/// Find the byte ranges of runs of the given classes in `text`.
fn char_runs(text: &str, digits: &str, letters: &str, separators: &str) -> Vec<(usize, usize)> {
    let bytes = text.as_bytes();
    let mut res = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        let start = i;
        let c = bytes[i];
        if digits.as_bytes().contains(&c) {
            while i < bytes.len() && digits.as_bytes().contains(&bytes[i]) {
                i += 1;
            }
        } else if letters.as_bytes().contains(&c) {
            while i < bytes.len() && letters.as_bytes().contains(&bytes[i]) {
                i += 1;
            }
        } else if separators.as_bytes().contains(&c) {
            i += 1;
        } else {
            i += 1;
            continue;
        }
        res.push((start, i));
    }
    res
}

fn push_plain_style(
    out: &mut Vec<Piece>,
    text: &str,
    number: &Style,
    letter: &Style,
    separator: &Style,
) {
    for (s, e) in char_runs(text, "0123456789", "abcdefABCDEF", ":.") {
        let sub = &text[s..e];
        if sub.as_bytes()[0].is_ascii_digit() {
            push_color(out, sub, number);
        } else if sub.as_bytes()[0] == b':' || sub.as_bytes()[0] == b'.' {
            push_color(out, sub, separator);
        } else {
            push_color(out, sub, letter);
        }
    }
}

fn runs<F: Fn(u8) -> bool>(text: &str, pred: F) -> Vec<(usize, usize)> {
    let bytes = text.as_bytes();
    let mut res = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        let start = i;
        if pred(bytes[i]) {
            while i < bytes.len() && pred(bytes[i]) {
                i += 1;
            }
            res.push((start, i));
        } else {
            i += 1;
        }
    }
    res
}

/// Try to parse an ipv6 address at the beginning of `bytes`, returning its
/// length in bytes when successful.
fn find_ipv6(bytes: &[u8]) -> Option<usize> {
    ipv6_try(bytes)
}

fn ipv6_try(b: &[u8]) -> Option<usize> {
    // eight groups separated by colons
    if let Some(len) = ipv6_groups(b, 8, None) {
        return Some(len);
    }
    // six groups followed by an ipv4 address
    if let Some(len) = ipv6_ipv4(b, 6, None) {
        return Some(len);
    }
    // groups :: groups, optionally ending with an ipv4 address
    for total in 0..=7usize {
        for k in 0..=total {
            let m = total - k;
            if let Some(len) = ipv6_groups(b, k, Some(m)) {
                return Some(len);
            }
            if m == 0 {
                if let Some(len) = ipv6_ipv4(b, k, Some(m)) {
                    return Some(len);
                }
            }
        }
    }
    None
}

fn group(b: &[u8], i: usize) -> usize {
    let mut j = i;
    while j < b.len() && b[j].is_ascii_hexdigit() && j - i < 4 {
        j += 1;
    }
    j - i
}

fn ipv4_at(b: &[u8], i: usize) -> Option<usize> {
    let mut j = i;
    for n in 0..4 {
        if n > 0 {
            if j >= b.len() || b[j] != b'.' {
                return None;
            }
            j += 1;
        }
        let start = j;
        let mut digits = 0;
        while j < b.len() && b[j].is_ascii_digit() && digits < 3 {
            j += 1;
            digits += 1;
        }
        if digits == 0 {
            return None;
        }
        let v: u32 = std::str::from_utf8(&b[start..j]).unwrap().parse().unwrap();
        if v > 255 {
            return None;
        }
    }
    // optional cidr suffix
    let mut end = j;
    if end < b.len() && b[end] == b'/' {
        let mut k = end + 1;
        let mut digits = 0;
        while k < b.len() && b[k].is_ascii_digit() && digits < 2 {
            k += 1;
            digits += 1;
        }
        if digits == 0 {
            return None;
        }
        if k < b.len() && (b[k].is_ascii_digit()) {
            return None;
        }
        end = k;
    }
    Some(end - i)
}

/// Match `k` groups followed by an ipv4 address. `after` is the number of
/// groups that must follow an optional `::` separator.
fn ipv6_ipv4(b: &[u8], k: usize, after: Option<usize>) -> Option<usize> {
    let mut i = 0;
    for _ in 0..k {
        if i > 0 && (i >= b.len() || b[i] != b':') {
            return None;
        }
        if i < b.len() && b[i] == b':' {
            i += 1;
        }
        let len = group(b, i);
        if len == 0 {
            return None;
        }
        i += len;
    }
    // ipv4
    if let Some(len) = ipv4_at(b, i) {
        if after.is_none() {
            return Some(i + len);
        }
        // after a :: separator, the remaining groups must match
        let mut j = i + len;
        let after = after.unwrap();
        if after == 0 {
            return Some(i + len);
        }
        for _ in 0..after {
            if j >= b.len() || b[j] != b':' {
                return None;
            }
            j += 1;
            let len = group(b, j);
            if len == 0 {
                return None;
            }
            j += len;
        }
        return Some(j);
    }
    None
}

fn ipv6_groups(b: &[u8], k: usize, after: Option<usize>) -> Option<usize> {
    let mut i = 0;
    for _ in 0..k {
        let len = group(b, i);
        if len == 0 {
            return None;
        }
        i += len;
        if i >= b.len() || b[i] != b':' {
            return None;
        }
        i += 1;
    }
    if let Some(m) = after {
        // k groups, then ::, then m groups
        if i >= b.len() || b[i] != b':' {
            return None;
        }
        i += 1;
        if i >= b.len() || b[i] != b':' {
            return None;
        }
        i += 1;
        for _ in 0..m {
            let len = group(b, i);
            if len == 0 {
                return None;
            }
            i += len;
            if i < b.len() && b[i] == b':' {
                i += 1;
            }
        }
        Some(i)
    } else {
        if k == 8 {
            Some(i)
        } else {
            None
        }
    }
}
