}

/// Parse `count` groups, each one followed by a colon.
fn groups_with_colon(b: &[u8], count: usize) -> Option<usize> {
    let mut i = 0;
    for _ in 0..count {
        let len = group_len(b, i);
        if len == 0 {
            return None;
        }
        i += len;
        if i >= b.len() || b[i] != b':' {
            return None;
        }
        i += 1;
    }
    Some(i)
