//! IPv6 address detection, implemented without lookarounds so that the same
//! boundaries as the original tool can be reproduced.
fn group_len(b: &[u8], i: usize) -> usize {
    let mut j = i;
    while j < b.len() && j - i < 4 && b[j].is_ascii_hexdigit() {
        j += 1;
    }
    j - i
}

/// Parse an ipv4 address (with an optional /nn suffix) at position `i`.
fn ipv4_len(b: &[u8], i: usize) -> Option<usize> {
    let mut j = i;
    for n in 0..4 {
        if n > 0 {
            if j >= b.len() || b[j] != b'.' {
                return None;
            }
            j += 1;
        }
        let start = j;
        let mut digits = 0;
        while j < b.len() && b[j].is_ascii_digit() && digits < 3 {
            j += 1;
            digits += 1;
        }
        if digits == 0 {
            return None;
        }
        let value: u32 = std::str::from_utf8(&b[start..j])
            .ok()?
            .parse()
            .ok()?;
        if value > 255 {
            return None;
        }
    }
    let mut end = j;
    if end < b.len() && b[end] == b'/' {
        let mut k = end + 1;
        let mut digits = 0;
        while k < b.len() && b[k].is_ascii_digit() && digits < 2 {
            k += 1;
            digits += 1;
        }
        if digits == 0 || (k < b.len() && b[k].is_ascii_digit()) {
            return None;
        }
        end = k;
    }
    Some(end - i)
}

/// Parse `count` groups, each one followed by a colon.
fn groups_with_colon(b: &[u8], count: usize) -> Option<usize> {
    let mut i = 0;
    for _ in 0..count {
        let len = group_len(b, i);
        if len == 0 {
            return None;
        }
        i += len;
        if i >= b.len() || b[i] != b':' {
            return None;
        }
        i += 1;
    }
    Some(i)
}

/// Parse `count` groups separated by colons, the last one not followed by one.
fn groups_tail(b: &[u8], count: usize) -> Option<usize> {
    let mut i = 0;
    for k in 0..count {
        let len = group_len(b, i);
        if len == 0 {
            return None;
        }
        i += len;
        if k + 1 < count {
            if i >= b.len() || b[i] != b':' {
                return None;
            }
            i += 1;
        }
    }
    Some(i)
}

/// Parse a compressed form: `head :: tail`, where the head has `head_groups`
/// groups and the tail has `tail_groups` groups.
fn compressed_len(b: &[u8], head_groups: usize, tail_groups: usize) -> Option<usize> {
    let mut i = groups_with_colon(b, head_groups)?;
    if i >= b.len() || b[i] != b':' {
        return None;
    }
    i += 1;
    if i >= b.len() || b[i] != b':' {
        return None;
    }
    i += 1;
    let tail = groups_tail(&b[i..], tail_groups)?;
    Some(i + tail)
}

/// Parse a compressed form that ends with an ipv4 address.
fn compressed_ipv4_len(b: &[u8], head_groups: usize, tail_groups: usize) -> Option<usize> {
    let mut i = compressed_len(b, head_groups, tail_groups)?;
    let len = ipv4_len(&b[i..], 0)?;
    Some(i + len)
}

/// Try to match an ipv6 address at the beginning of `b`, returning the length.
pub fn ipv6_len(b: &[u8]) -> Option<usize> {
    // eight plain groups
    if let Some(i) = groups_with_colon(b, 7) {
        let len = group_len(b, i);
        if len > 0 {
            return Some(i + len);
        }
    }
    // six plain groups followed by an ipv4 address
    if let Some(i) = groups_with_colon(b, 6) {
        if let Some(l) = ipv4_len(&b[i..], 0) {
            return Some(i + l);
        }
    }
    // compressed forms without an ipv4 tail: head + tail <= 7
    for total in 0..=7usize {
        for head in (0..=total).rev() {
            let tail = total - head;
            if let Some(len) = compressed_len(b, head, tail) {
                return Some(len);
            }
        }
    }
    // compressed forms with an ipv4 tail: head + tail <= 5
    for total in 0..=5usize {
        for head in (0..=total).rev() {
            let tail = total - head;
            if let Some(len) = compressed_ipv4_len(b, head, tail) {
                return Some(len);
            }
        }
    }
    None
}

/// True when the byte can continue an ipv6 address.
pub fn continues_ipv6(c: u8) -> bool {
    c.is_ascii_hexdigit() || c == b':' || c == b'.'
}

/// True when the byte can start an ipv6 address.
pub fn starts_ipv6(c: u8) -> bool {
    c.is_ascii_hexdigit() || c == b':'
}
