            push_plain(&mut out, &text[last..m.start()]);
            push_color(&mut out, caps.name("name").unwrap().as_str(), &name);
            push_color(&mut out, "[", &bracket);
            push_color(&mut out, caps.name("pid").unwrap().as_str(), &id);
            push_color(&mut out, "]", &bracket);
            last = m.end();
        }
        if any {
            push_plain(&mut out, &text[last..]);
            return Some(out);
        }
        None
    });
    Highlighter { run }
}

// ------------------------------------------------------------ keywords ------

/// A list of words that are highlighted with the same style.
pub struct Keywords {
    pub re: Regex,
    pub style: Style,
}

impl Keywords {
    /// Match the words and pad them with spaces when a background color is set.
    pub fn highlighter(&self) -> Highlighter {
        let re = self.re.clone();
        let style = self.style.clone();
        let run: HighlighterFn = Box::new(move |text: &str| {
            let mut out: Vec<Piece> = Vec::new();
            let mut last = 0;
            let mut any = false;
            for m in re.find_iter(text) {
                any = true;
                push_plain(&mut out, &text[last..m.start()]);
                if style.bg.is_some() {
                    let padded = format!(" {} ", m.as_str());
                    push_color(&mut out, &padded, &style);
                } else {
                    push_color(&mut out, m.as_str(), &style);
                }
                last = m.end();
            }
            if any {
                push_plain(&mut out, &text[last..]);
                return Some(out);
            }
            None
        });
        Highlighter { run }
    }
}

/// Build a keyword group from a list of words and a style.
pub fn keywords(words: &[String], style: Style) -> Option<Keywords> {
    if words.is_empty() {
        return None;
    }
    let mut sorted: Vec<&String> = words.iter().collect();
    sorted.sort_by_key(|w| w.len());
    let escaped: Vec<String> = sorted.iter().map(|w| regex::escape(w)).collect();
    let pattern = format!(r"\b(?:{})\b", escaped.join("|"));
    let re = Regex::new(&pattern).ok()?;
    Some(Keywords { re, style })
}

// -------------------------------------------------------------- quotes ------

pub fn quote_highlighter(theme: &Theme) -> Highlighter {
    let style = theme.quotes_style();
    let re = Regex::new(r#""[^"]*""#).unwrap();
    let run: HighlighterFn = Box::new(move |text: &str| {
        if text.matches('"').count() % 2 != 0 {
            return None;
        }
        let mut out: Vec<Piece> = Vec::new();
        let mut last = 0;
        let mut any = false;
        for m in re.find_iter(text) {
            any = true;
            push_plain(&mut out, &text[last..m.start()]);
            push_color(&mut out, m.as_str(), &style);
            last = m.end();
        }
        if any {
            push_plain(&mut out, &text[last..]);
            return Some(out);
        }
        None
    });
    Highlighter { run }
}
