//! All builtin highlighters together with the logic that renders a line.
use regex::Regex;

use crate::ipv6::{continues_ipv6, ipv6_len, starts_ipv6};
use crate::theme::{Color, Style, Theme};

/// The regex for a date part (YYYY-MM-DD or YYYY/MM/DD).
const DATE: &str = r"(19|20)\d{2}[-/](0[1-9]|[12]\d|3[01])[-/](0[1-9]|[12]\d|3[01])";
/// The regex for a time part (HH:MM:SS with an optional fraction).
const TIME: &str = r"([01]?\d|2[0-3]):([0-5]\d):([0-5]\d)([.,:]\d+)?";

/// Class of characters that are valid in an url path.
const URL_PATH_CHARS: &str = r"[0-9A-Za-z._~+%/-]";
/// Class of characters that are valid in an url query key or value.
const URL_QUERY_CHARS: &str = r"[0-9A-Za-z._~+%+-]";
/// Class of characters that are valid in a path segment.
const SEGMENT_CHARS: &str = r"[0-9A-Za-z._-]";
/// Class of characters that are valid in an octet of an ip address.
const OCTET: &str = r"(?:25[0-5]|2[0-4]\d|[01]?\d\d?)";

/// Styles that cannot be configured through the theme file.
#[derive(Clone)]
pub struct Builtin {
    pub date_fill: Style,
    pub tz: Style,
    pub hex_number: Style,
    pub hex_letter: Style,
    pub hex_separator: Style,
    pub pointer_prefix: Style,
    pub url_query_separator: Style,
    pub url_query_name: Style,
    pub url_query_value: Style,
    pub json_structural: Style,
}

impl Builtin {
    pub fn new() -> Builtin {
        Builtin {
            date_fill: Style::fg(Color::Red),
            tz: Style::fg(Color::Red),
            hex_number: Style {
                italic: true,
                fg: Some(Color::Blue),
                ..Default::default()
            },
            hex_letter: Style {
                italic: true,
                fg: Some(Color::Magenta),
                ..Default::default()
            },
            hex_separator: Style::fg(Color::Red),
            pointer_prefix: Style::fg(Color::Red),
            url_query_separator: Style::fg(Color::Red),
            url_query_name: Style::fg(Color::Magenta),
            url_query_value: Style::fg(Color::Cyan),
            json_structural: Style {
                faint: true,
                ..Default::default()
            },
        }
    }
}

fn push_color(out: &mut Vec<Piece>, text: &str, style: &Style) {
    if !text.is_empty() {
        out.push(Piece::styled(text, style.clone()));
    }
}

fn push_plain(out: &mut Vec<Piece>, text: &str) {
    if !text.is_empty() {
        out.push(Piece::unstyled(text));
    }
}

/// Push runs of digits and separators, styled separately.
fn push_digit_sep(out: &mut Vec<Piece>, text: &str, digit: &Style, sep: &Style, seps: &[u8]) {
    let bytes = text.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let start = i;
        if bytes[i].is_ascii_digit() {
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                i += 1;
            }
            push_color(out, &text[start..i], digit);
        } else if seps.contains(&bytes[i]) {
            i += 1;
            push_color(out, &text[start..i], sep);
        } else {
            i += 1;
            push_plain(out, &text[start..i]);
        }
    }
}

/// Push every single character of `text` as its own span, styling digits and
/// hex letters differently.
fn push_hex_chars(out: &mut Vec<Piece>, text: &str, number: &Style, letter: &Style, sep: &Style, seps: &[u8]) {
    for c in text.chars() {
        let mut buf = [0u8; 4];
        let s = c.encode_utf8(&mut buf);
        if c.is_ascii_digit() {
            push_color(out, s, number);
        } else if c.is_ascii_hexdigit() {
            push_color(out, s, letter);
        } else if seps.contains(&(c as u8)) {
            push_color(out, s, sep);
        } else {
            push_plain(out, s);
        }
    }
}

// ---------------------------------------------------------------- json -------

fn render_json(value: &serde_json::Value, out: &mut Vec<Piece>, key: &Style, structural: &Style) {
    use serde_json::Value as V;
    match value {
        V::Object(map) => {
            push_color(out, "{", structural);
            let mut first = true;
            for (k, v) in map {
                if !first {
                    push_color(out, ",", structural);
                }
                first = false;
                push_plain(out, " ");
                push_color(out, "\"", structural);
                push_color(out, k, key);
                push_color(out, "\"", structural);
                push_color(out, ":", structural);
                push_plain(out, " ");
                render_json(v, out, key, structural);
            }
            push_plain(out, " ");
            push_color(out, "}", structural);
        }
        V::Array(items) => {
            push_color(out, "[", structural);
            let mut first = true;
            for v in items {
                if !first {
                    push_color(out, ",", structural);
                    push_plain(out, " ");
                }
                first = false;
                render_json(v, out, key, structural);
            }
            push_color(out, "]", structural);
        }
        V::String(s) => {
            push_color(out, "\"", structural);
            push_plain(out, s);
            push_color(out, "\"", structural);
        }
        other => push_plain(out, &other.to_string()),
    }
}

pub fn json_highlighter(theme: &Theme, builtin: &Builtin) -> Highlighter {
    let key_style = theme.json_key_style();
    let structural = builtin.json_structural.clone();
    let run: HighlighterFn = Box::new(move |text: &str| {
        let value: serde_json::Value = match serde_json::from_str(text) {
            Ok(v) => v,
            Err(_) => return None,
        };
        let mut out = Vec::new();
        render_json(&value, &mut out, &key_style, &structural);
        Some(out)
    });
    Highlighter { run }
}

// -------------------------------------------------------------- dates -------

pub fn date_highlighter(theme: &Theme, builtin: &Builtin) -> Highlighter {
    let date_style = theme.date_style();
    let time_style = theme.time_style();
    let sep_style = theme.date_separator_style();
    let fill = builtin.date_fill.clone();
    let tz = builtin.tz.clone();

    let datetime_re = Regex::new(&format!(r"(?P<date>{})[ \tT](?P<time>{})Z?", DATE, TIME)).unwrap();
    let date_re = Regex::new(&format!(r"(?P<date>{})", DATE)).unwrap();
    let time_re = Regex::new(&format!(r"(?P<time>{})Z?", TIME)).unwrap();

    let run: HighlighterFn = Box::new(move |text: &str| {
        for re in [&datetime_re, &date_re, &time_re] {
            let mut out: Vec<Piece> = Vec::new();
            let mut last = 0;
            let mut matched = false;
            for caps in re.captures_iter(text) {
                matched = true;
                let start = caps.get(0).unwrap().start();
                let end = caps.get(0).unwrap().end();
                push_plain(&mut out, &text[last..start]);
                match (caps.name("date"), caps.name("time")) {
                    (Some(d), Some(t)) => {
                        push_digit_sep(&mut out, d.as_str(), &date_style, &sep_style, b"-/");
                        push_color(&mut out, &text[d.end()..t.start()], &fill);
                        push_digit_sep(&mut out, t.as_str(), &time_style, &sep_style, b":,.");
                        if text.as_bytes().get(end.wrapping_sub(1)) == Some(&b'Z') {
                            push_color(&mut out, "Z", &tz);
                        }
                    }
                    (Some(d), None) => {
                        push_digit_sep(&mut out, d.as_str(), &date_style, &sep_style, b"-/");
                    }
                    (None, Some(t)) => {
                        push_digit_sep(&mut out, t.as_str(), &time_style, &sep_style, b":,.");
                        if text.as_bytes().get(end.wrapping_sub(1)) == Some(&b'Z') {
                            push_color(&mut out, "Z", &tz);
                        }
                    }
                    _ => {}
                }
                last = end;
            }
            if matched {
                push_plain(&mut out, &text[last..]);
                return Some(out);
            }
        }
        None
    });
    Highlighter { run }
}

// -------------------------------------------------------- ip addresses ------

pub fn ip_highlighter(_theme: &Theme, builtin: &Builtin) -> Highlighter {
    let number = builtin.hex_number.clone();
    let letter = builtin.hex_letter.clone();
    let separator = builtin.hex_separator.clone();
    let ipv4_re = Regex::new(&format!(
        r"\b(?P<ip>(?:{}\.){3}{})?(?P<cidr>/\d{{1,2}})?\b",
        OCTET, OCTET
    ))
    .unwrap();
    let ipv4_re = Regex::new(&format!(
        r"\b(?P<ip>(?:{}\.){3}{})(?P<cidr>/\d{{1,2}})?\b",
        OCTET, OCTET
    ))
    .unwrap();

    let run: HighlighterFn = Box::new(move |text: &str| {
        let bytes = text.as_bytes();
        let mut ipv6_out: Vec<Piece> = Vec::new();
        let mut last = 0;
        let mut i = 0;
        let mut matched = false;
        while i <= bytes.len() {
            if i > 0 && starts_ipv6(bytes[i - 1]) {
                i += 1;
                continue;
            }
            match ipv6_len(&bytes[i..]) {
                Some(len) => {
                    let end = i + len;
                    if end < bytes.len() && continues_ipv6(bytes[end]) {
                        i += 1;
                        continue;
                    }
                    push_plain(&mut ipv6_out, &text[last..i]);
                    push_hex_chars(
                        &mut ipv6_out,
                        &text[i..end],
                        &number,
                        &letter,
                        &separator,
                        b":.",
                    );
                    last = end;
                    matched = true;
                    i = end;
                }
                None => {
                    i += 1;
                }
            }
        }
        if matched {
            push_plain(&mut ipv6_out, &text[last..]);
            return Some(ipv6_out);
        }
        let mut out: Vec<Piece> = Vec::new();
        let mut last = 0;
        let mut any = false;
        for caps in ipv4_re.captures_iter(text) {
            any = true;
            let start = caps.get(0).unwrap().start();
            let end = caps.get(0).unwrap().end();
            push_plain(&mut out, &text[last..start]);
            let ip = caps.name("ip").unwrap();
            let mut ip_out = Vec::new();
            push_digit_sep(&mut ip_out, ip.as_str(), &number, &separator, b".");
            out.append(&mut ip_out);
            if let Some(c) = caps.name("cidr") {
                push_color(&mut out, "/", &separator);
                push_digit_sep(&mut out, &c.as_str()[1..], &number, &separator, b".");
            }
            last = end;
        }
        if any {
            push_plain(&mut out, &text[last..]);
            return Some(out);
        }
        None
    });
    Highlighter { run }
}

// --------------------------------------------------------------- urls -------

pub fn url_highlighter(theme: &Theme, builtin: &Builtin) -> Highlighter {
    let http = theme.url_http_style();
    let https = theme.url_https_style();
    let host = theme.url_host_style();
    let path = theme.url_path_style();
    let q_sep = builtin.url_query_separator.clone();
    let q_name = builtin.url_query_name.clone();
    let q_value = builtin.url_query_value.clone();

    let url_re = Regex::new(&format!(
        r"(?P<scheme>https?)://(?P<host>[0-9A-Za-z._-]+)(?P<path>{}*)(?P<query>\?[^# \t\r]*)?",
        URL_PATH_CHARS
    ))
    .unwrap();
    let query_re = Regex::new(&format!(
        r"[?&]({}*)=({}*)",
        URL_QUERY_CHARS, URL_QUERY_CHARS
    ))
    .unwrap();

    let run: HighlighterFn = Box::new(move |text: &str| {
        let mut out: Vec<Piece> = Vec::new();
        let mut last = 0;
        let mut any = false;
        for caps in url_re.captures_iter(text) {
            any = true;
            let m = caps.get(0).unwrap();
            push_plain(&mut out, &text[last..m.start()]);
            let scheme = caps.name("scheme").unwrap();
            let style = if scheme.as_str() == "https" { &https } else { &http };
            push_color(&mut out, scheme.as_str(), style);
            push_plain(&mut out, "://");
            let hostm = caps.name("host").unwrap();
            push_color(&mut out, hostm.as_str(), &host);
            let pathm = caps.name("path").unwrap();
            push_color(&mut out, pathm.as_str(), &path);
            if let Some(qm) = caps.name("query") {
                if let Some(q) = qm {
                    let mut lastq = 0;
                    for qc in query_re.captures_iter(q.as_str()) {
                        let qm0 = qc.get(0).unwrap();
                        push_plain(&mut out, &q.as_str()[lastq..qm0.start()]);
                        let sep_len = 1;
                        push_color(&mut out, &q.as_str()[qm0.start()..qm0.start() + sep_len], &q_sep);
                        let name = qc.get(1).unwrap();
                        push_color(&mut out, name.as_str(), &q_name);
                        push_color(&mut out, "=", &q_sep);
                        let value = qc.get(2).unwrap();
                        push_color(&mut out, value.as_str(), &q_value);
                        lastq = qm0.end();
                    }
                    push_plain(&mut out, &q.as_str()[lastq..]);
                }
            }
            last = m.end();
        }
        if any {
            push_plain(&mut out, &text[last..]);
            return Some(out);
        }
        None
    });
    Highlighter { run }
}

// -------------------------------------------------------------- paths -------

pub fn path_highlighter(theme: &Theme) -> Highlighter {
    let segment = theme.path_segment_style();
    let separator = theme.path_separator_style();

    let re = Regex::new(&format!(
        r"(?P<tilde>~)?(?P<seg1>{}*)?(?P<sep>/)(?P<seg2>{}+)(?P<rest>(?:/(?:{}+))+)",
        SEGMENT_CHARS, SEGMENT_CHARS, SEGMENT_CHARS
    ))
    .unwrap();

    let run: HighlighterFn = Box::new(move |text: &str| {
        let mut out: Vec<Piece> = Vec::new();
        let mut last = 0;
        let mut any = false;
        for caps in re.captures_iter(text) {
            any = true;
            let m = caps.get(0).unwrap();
            push_plain(&mut out, &text[last..m.start()]);
            if let Some(t) = caps.name("tilde") {
                if let Some(t) = t {
                    push_color(&mut out, t.as_str(), &segment);
                }
            }
            if let Some(s) = caps.name("seg1") {
                if let Some(s) = s {
                    push_color(&mut out, s.as_str(), &segment);
                }
            }
            let sep = caps.name("sep").unwrap();
            push_color(&mut out, sep.as_str(), &separator);
            let seg2 = caps.name("seg2").unwrap();
            push_color(&mut out, seg2.as_str(), &segment);
            if let Some(r) = caps.name("rest") {
                if let Some(r) = r {
                    for part in r.as_str().split('/') {
                        if part.is_empty() {
                            continue;
                        }
                        push_color(&mut out, "/", &separator);
                        push_color(&mut out, part, &segment);
                    }
                }
            }
            last = m.end();
        }
        if any {
            push_plain(&mut out, &text[last..]);
            return Some(out);
        }
        None
    });
    Highlighter { run }
}

// ------------------------------------------------------------ numbers -------

pub fn number_highlighter(theme: &Theme) -> Highlighter {
    let style = theme.number_style();
    let re = Regex::new(r"\b\d+(\.\d+)?\b").unwrap();
    let run: HighlighterFn = Box::new(move |text: &str| {
        let mut out: Vec<Piece> = Vec::new();
        let mut last = 0;
        let mut any = false;
        for m in re.find_iter(text) {
            any = true;
            push_plain(&mut out, &text[last..m.start()]);
            push_color(&mut out, m.as_str(), &style);
            last = m.end();
        }
        if any {
            push_plain(&mut out, &text[last..]);
            return Some(out);
        }
        None
    });
    Highlighter { run }
}

// ---------------------------------------------------- key value pairs -------

pub fn key_value_highlighter(theme: &Theme) -> Highlighter {
    let key = theme.key_value_key_style();
    let sep = theme.key_value_separator_style();
    let re = Regex::new(r"(?P<key>[0-9A-Za-z_]+)(?P<sep>=)(?P<value>\S*)").unwrap();
    let run: HighlighterFn = Box::new(move |text: &str| {
        let mut out: Vec<Piece> = Vec::new();
        let mut last = 0;
        let mut any = false;
        for caps in re.captures_iter(text) {
            any = true;
            let m = caps.get(0).unwrap();
            push_plain(&mut out, &text[last..m.start()]);
            let k = caps.name("key").unwrap();
            push_color(&mut out, k.as_str(), &key);
            push_color(&mut out, "=", &sep);
            last = m.end();
        }
        if any {
            push_plain(&mut out, &text[last..]);
            return Some(out);
        }
        None
    });
    Highlighter { run }
}

// ------------------------------------------------------------ pointers ------

pub fn pointer_highlighter(theme: &Theme, builtin: &Builtin) -> Highlighter {
    let number = theme.pointer_number_style();
    let letter = theme.pointer_letter_style();
    let separator = theme.pointer_separator_style();
    let prefix = builtin.pointer_prefix.clone();
    let re = Regex::new(r"\b0[xX][0-9a-fA-F]{8}\b|\b0[xX][0-9a-fA-F]{16}\b").unwrap();
    let run: HighlighterFn = Box::new(move |text: &str| {
        let mut out: Vec<Piece> = Vec::new();
        let mut last = 0;
        let mut any = false;
        for m in re.find_iter(text) {
            any = true;
            push_plain(&mut out, &text[last..m.start()]);
            let s = m.as_str();
            push_color(&mut out, &s[..1], &number);
            push_color(&mut out, &s[1..2], &prefix);
            let digits = &s[2..];
            if digits.len() == 16 {
                push_hex_chars(&mut out, &digits[..8], &number, &letter, &separator, b"-/.,:");
                push_color(&mut out, "•", &separator);
                push_hex_chars(&mut out, &digits[8..], &number, &letter, &separator, b"-/.,:");
            } else {
                push_hex_chars(&mut out, digits, &number, &letter, &separator, b"-/.,:");
            }
            last = m.end();
        }
        if any {
            push_plain(&mut out, &text[last..]);
            return Some(out);
        }
        None
    });
    Highlighter { run }
}

// ----------------------------------------------------------- processes ------

pub fn process_highlighter(theme: &Theme) -> Highlighter {
    let name = theme.process_name_style();
    let id = theme.process_id_style();
    let bracket = theme.process_bracket_style();
    let re = Regex::new(r"(?P<name>\([^)]+\)|[0-9A-Za-z_/-]+)\[(?P<pid>\d+(\.\d+)?)\]").unwrap();
    let run: HighlighterFn = Box::new(move |text: &str| {
        let mut out: Vec<Piece> = Vec::new();
        let mut last = 0;
        let mut any = false;
        for caps in re.captures_iter(text) {
            any = true;
            let m = caps.get(0).unwrap();
            push_plain(&mut out, &text[last..m.start()]);
            push_color(&mut out, caps.name("name").unwrap().as_str(), &name);
            push_color(&mut out, "[", &bracket);
            push_color(&mut out, caps.name("pid").unwrap().as_str(), &id);
            push_color(&mut out, "]", &bracket);
            last = m.end();
        }
        if any {
            push_plain(&mut out, &text[last..]);
            return Some(out);
        }
        None
    });
    Highlighter { run }
}

// ------------------------------------------------------------ keywords ------

/// A list of words that are highlighted with the same style.
pub struct Keywords {
    pub re: Regex,
    pub style: Style,
}

impl Keywords {
    /// Match the words and pad them with spaces when a background color is set.
    pub fn highlighter(&self) -> Highlighter {
        let re = self.re.clone();
        let style = self.style.clone();
        let run: HighlighterFn = Box::new(move |text: &str| {
            let mut out: Vec<Piece> = Vec::new();
            let mut last = 0;
            let mut any = false;
            for m in re.find_iter(text) {
                any = true;
                push_plain(&mut out, &text[last..m.start()]);
                if style.bg.is_some() {
                    let padded = format!(" {} ", m.as_str());
                    push_color(&mut out, &padded, &style);
                } else {
                    push_color(&mut out, m.as_str(), &style);
                }
                last = m.end();
            }
            if any {
                push_plain(&mut out, &text[last..]);
                return Some(out);
            }
            None
        });
        Highlighter { run }
    }
}

/// Build a keyword group from a list of words and a style.
pub fn keywords(words: &[String], style: Style) -> Option<Keywords> {
    if words.is_empty() {
        return None;
    }
    let mut sorted: Vec<&String> = words.iter().collect();
    sorted.sort_by_key(|w| w.len());
    let escaped: Vec<String> = sorted.iter().map(|w| regex::escape(w)).collect();
    let pattern = format!(r"\b(?:{})\b", escaped.join("|"));
    let re = Regex::new(&pattern).ok()?;
    Some(Keywords { re, style })
}

// -------------------------------------------------------------- quotes ------

pub fn quote_highlighter(theme: &Theme) -> Highlighter {
    let style = theme.quotes_style();
    let re = Regex::new(r#""[^"]*""#).unwrap();
    let run: HighlighterFn = Box::new(move |text: &str| {
        if text.matches('"').count() % 2 != 0 {
            return None;
        }
        let mut out: Vec<Piece> = Vec::new();
        let mut last = 0;
        let mut any = false;
        for m in re.find_iter(text) {
            any = true;
            push_plain(&mut out, &text[last..m.start()]);
            push_color(&mut out, m.as_str(), &style);
            last = m.end();
        }
        if any {
            push_plain(&mut out, &text[last..]);
            return Some(out);
        }
        None
    });
    Highlighter { run }
}
EOF
