//! The highlighting engine: pieces of a line and how highlighters split them.
use crate::theme::Style;

/// One piece of a line, optionally styled.
#[derive(Debug, Clone)]
pub struct Piece {
    pub text: String,
    pub style: Option<Style>,
}

impl Piece {
    pub fn unstyled(text: &str) -> Piece {
        Piece {
            text: text.to_string(),
            style: None,
        }
    }
    pub fn styled(text: &str, style: Style) -> Piece {
        Piece {
            text: text.to_string(),
            style: Some(style),
        }
    }
}

pub type HighlighterFn = Box<dyn Fn(&str) -> Option<Vec<Piece>> + Send + Sync>;

/// A highlighter runs on the contiguous runs of text that have not been
/// highlighted by a highlighter with a higher priority.
pub struct Highlighter {
    pub run: HighlighterFn,
}

impl Highlighter {
    pub fn apply(&self, pieces: &mut Vec<Piece>) {
        let mut result: Vec<Piece> = Vec::new();
        let mut pending = String::new();
        for piece in pieces.drain(..) {
            if piece.style.is_some() {
                if !pending.is_empty() {
                    match (self.run)(&pending) {
                        Some(new) => result.extend(new),
                        None => result.push(Piece::unstyled(&pending)),
                    }
                    pending.clear();
                }
                result.push(piece);
            } else {
                pending.push_str(&piece.text);
            }
        }
        if !pending.is_empty() {
            match (self.run)(&pending) {
                Some(new) => result.extend(new),
                None => result.push(Piece::unstyled(&pending)),
            }
        }
        *pieces = result;
    }
}
