//! Errors together with the way they are printed on stderr.
use crate::theme::RESET;

pub type Result<T> = std::result::Result<T, TspinError>;

/// Every error that tspin can produce.
#[derive(Debug)]
pub enum TspinError {
    /// The provided file cannot be read.
    IoError(String, std::io::Error),
    /// The provided path is not a file.
    NotAFile,
    /// The file could not be opened.
    OpenError(String, std::io::Error),
    /// The configuration file could not be found.
    TomlNotFound,
    /// The configuration file could not be read.
    TomlRead(String, std::io::Error),
    /// The configuration file could not be parsed.
    TomlParse(String),
    /// Both --enable and --disable were provided.
    BothEnableAndDisable,
    /// The home directory could not be determined.
    HomeEnvironment(String),
    /// The custom pager command could not be parsed.
    PagerParse,
    /// The pager could not be started.
    PagerSpawn(String, std::io::Error),
}

impl TspinError {
    /// The kind of the error, printed on its own line when not empty.
    pub fn kind(&self) -> &'static str {
        match self {
            TspinError::PagerSpawn(..) => "less::command_spawn",
            _ => "",
        }
    }

    /// The message that is rendered next to the cross.
    pub fn message(&self) -> String {
        match self {
            TspinError::IoError(path, e) => format!(
                "⚠ \x1b[33m{}\x1b[0m: {}",
                path,
                e
            ),
            TspinError::NotAFile => "Path is not a file".to_string(),
            TspinError::OpenError(path, e) => format!("Could not open file: {:?}: {}", path, e),
            TspinError::TomlNotFound => "could not find the TOML file".to_string(),
            TspinError::TomlRead(msg, e) => format!("could not read the TOML file: {}: {}", msg, e),
            TspinError::TomlParse(msg) => msg.clone(),
            TspinError::BothEnableAndDisable => {
                "cannot both enable and disable highlighters".to_string()
            }
            TspinError::HomeEnvironment(msg) => {
                format!("could not determine the home environment: {}", msg)
            }
            TspinError::PagerParse => "Could not parse custom pager command".to_string(),
            TspinError::PagerSpawn(msg, e) => format!("Could not run pager: {}: {}", msg, e),
        }
    }

    /// The reasons that are printed below the message.
    pub fn causes(&self) -> Vec<String> {
        match self {
            TspinError::OpenError(_, e) => vec![e.to_string()],
            TspinError::TomlRead(_, e) => vec![e.to_string()],
            TspinError::PagerSpawn(_, e) => vec![e.to_string()],
            TspinError::HomeEnvironment(_) => vec!["environment variable not found".to_string()],
            _ => vec![],
        }
    }
}

/// Render the message the way it is printed: the first line next to a marker
/// and the following lines indented with a vertical bar.
pub fn render_message(message: &str, marker: &str) -> String {
    let mut lines = message.split('\n');
    let mut out = String::new();
    if let Some(first) = lines.next() {
        out.push_str(marker);
        out.push_str(first);
    }
    for line in lines {
        out.push_str("\n  │ ");
        out.push_str(line);
    }
    out
}

/// Print the error to stderr.
pub fn print_error(err: &TspinError) {
    let kind = err.kind();
    let (marker, message) = if kind.is_empty() {
        let m = err.message();
        if m.starts_with("⚠") {
            // the path is highlighted, the warning is part of the message
            let rendered = render_message(&format!("{}", m), "");
            (String::new(), rendered)
        } else {
            (String::new(), render_message(&m, "× "))
        }
    } else {
        eprintln!("Error: {}", kind);
        eprintln!();
        (String::new(), render_message(&err.message(), "× "))
    };
    if !marker.is_empty() {
        eprint!("Error:  {}", marker);
    } else if kind.is_empty() {
        eprint!("Error:  ");
    }
    eprint!("{}", message);
    eprintln!();
    for cause in err.causes() {
        eprintln!("  ╰─▶ {}", cause);
    }
    eprintln!();
    let _ = RESET;
}
EOF
