//! Running the pager (less by default) on a temporary file.
use std::path::{Path, PathBuf};
use std::process::Command;

use crate::error::{Result, TspinError};
use crate::theme::Style;

/// The command that is used when the user did not provide one.
pub const DEFAULT_PAGER: &str = "less --ignore-case --RAW-CONTROL-CHARS -- [FILE]";

/// The name given to temporary files.
pub const TEMP_PREFIX: &str = "tailspin.temp.";

/// A file that is highlighted and passed to the pager.
pub struct TempFile {
    dir: tempfile::TempDir,
    path: PathBuf,
}

impl TempFile {
    /// Create a new temporary file.
    pub fn new() -> TempFile {
        let dir = tempfile::tempdir().ok().unwrap_or_else(|| {
            tempfile::TempDir::new_in(".").expect("could not create a temporary file")
        });
        let path = dir.path().join(format!(
            "{}{}",
            TEMP_PREFIX,
            uuid::Uuid::new_v4()
        ));
        TempFile { dir, path }
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    pub fn write(&self, content: &str) -> std::io::Result<()> {
        std::fs::write(&self.path, content)
    }

    pub fn append(&self, content: &str) -> std::io::Result<()> {
        use std::io::Write;
        let mut f = std::fs::OpenOptions::new()
            .append(true)
            .create(true)
            .open(&self.path)?;
        f.write_all(content.as_bytes())
    }
}

/// Split a pager command into its arguments, replacing [FILE] with the path.
pub fn pager_command(pager: &str, file: &Path) -> Option<Vec<String>> {
    let parts = shlex::split(pager)?;
    if parts.iter().all(|p| p != "[FILE]") {
        return None;
    }
    Some(
        parts
            .into_iter()
            .map(|p| p.replace("[FILE]", &file.to_string_lossy()))
            .collect(),
    )
}

/// Run the pager on the given file and wait until it exits.
pub fn run_pager(pager: &str, file: &Path) -> Result<()> {
    let args = match pager_command(pager, file) {
        Some(args) => args,
        None => return Err(TspinError::PagerParse),
    };
    let mut cmd = Command::new(&args[0]);
    cmd.args(&args[1..]);
    match cmd.spawn() {
        Ok(mut child) => {
            let _ = child.wait();
            Ok(())
        }
        Err(e) => Err(TspinError::PagerSpawn(pager.to_string(), e)),
    }
}
