//! Following a file or a command and feeding the pager.
use std::io::Read;
use std::time::Duration;

use crate::error::{Result, TspinError};
use crate::highlighters::Highlighter;
use crate::hl::Highlighters;
use crate::less::TempFile;

/// Sleep interval used while following.
pub const POLL_INTERVAL: Duration = Duration::from_millis(1);

/// Highlight a single line, including the trailing newline.
pub fn highlight_line(line: &str, hl: &Highlighters) -> String {
    let mut out = hl.highlight(line);
    out.push('\n');
    out
}

/// Follow a file, appending the highlighted lines to the temp file.
pub fn follow_file(path: &str, temp: &TempFile, hl: &Highlighters) -> Result<()> {
    let mut file = std::fs::File::open(path).map_err(|e| TspinError::OpenError(path.to_string(), e))?;
    let mut pos: u64 = 0;
    loop {
        let mut buffer = Vec::new();
        {
            use std::io::{Seek, SeekFrom};
            let _ = file.seek(SeekFrom::Start(pos));
            let _ = file.read_to_end(&mut buffer);
        }
        if !buffer.is_empty() {
            let text = String::from_utf_lossy(&buffer).to_string();
            let (complete, consumed) = complete_lines(&text);
            let mut out = String::new();
            for line in complete {
                out.push_str(&highlight_line(&line, hl));
            }
            let _ = temp.append(&out);
            pos += consumed as u64;
        }
        std::thread::sleep(POLL_INTERVAL);
    }
}

/// Read lines from a reader, appending the highlighted ones to the temp file.
pub fn follow_reader<R: Read>(mut reader: R, temp: &TempFile, hl: &Highlighters) -> Result<()> {
    let mut buffer = Vec::new();
    let mut buf = [0u8; 8192];
    loop {
        match reader.read(&mut buf) {
            Ok(0) => {
                std::thread::sleep(POLL_INTERVAL);
                continue;
            }
            Ok(n) => buffer.extend_from_slice(&buf[..n]),
            Err(ref e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(TspinError::CommandRead("command".to_string(), e)),
        }
        let text = String::from_utf_lossy(&buffer).to_string();
        let (complete, consumed) = complete_lines(&text);
        let mut out = String::new();
        for line in complete {
            out.push_str(&highlight_line(&line, hl));
        }
        let _ = temp.append(&out);
        buffer.drain(..consumed);
    }
}

/// Split the text into complete lines and the remaining partial line.
fn complete_lines(text: &str) -> (Vec<String>, usize) {
    let mut lines = Vec::new();
    let mut start = 0;
    let mut consumed = 0;
    for (i, c) in text.char_indices() {
        if c == '\n' {
            lines.push(text[start..i].to_string());
            consumed = i + 1;
            start = i + 1;
        }
    }
    (lines, consumed)
}
EOF
echo ok"}

