// ------------------------------------------------------- highlighter set ----

/// All the highlighters in the order in which they are applied.
pub struct Highlighters {
    list: Vec<Highlighter>,
}

impl Highlighters {
    /// Render a single line of text.
    pub fn highlight(&self, line: &str) -> String {
        let mut pieces = vec![Piece::unstyled(line)];
        for h in &self.list {
            h.apply(&mut pieces);
        }
        let mut out = String::new();
        for piece in pieces {
            match &piece.style {
                Some(style) => {
                    let start = style.to_start();
                    if start.is_empty() {
                        out.push_str(&piece.text);
                    } else {
                        out.push_str(&start);
                        out.push_str(&piece.text);
                        out.push_str(crate::theme::RESET);
                    }
                }
                None => out.push_str(&piece.text),
            }
        }
        out
    }
}

/// The names of the groups that can be enabled or disabled.
pub const GROUP_NAMES: [&str; 11] = [
    "numbers",
    "urls",
    "pointers",
    "dates",
    "paths",
    "quotes",
    "key-value-pairs",
    "uuids",
    "ip-addresses",
    "processes",
    "json",
];

fn group_index(name: &str) -> Option<usize> {
    GROUP_NAMES.iter().position(|n| *n == name)
}

/// Build the list of highlighters.
pub fn build(
    theme: &Theme,
    builtin: &Builtin,
    enabled: Option<&[usize]>,
    disabled: &[usize],
    disable_builtin: bool,
    cli_keywords: &[(Vec<String>, Style)],
) -> Highlighters {
    let is_on = |idx: usize| -> bool {
        if let Some(en) = enabled {
            en.contains(&idx)
        } else {
            !disabled.contains(&idx)
        }
    };
    let mut list: Vec<Highlighter> = Vec::new();
    // json
    if is_on(group_index("json").unwrap()) {
        list.push(json_highlighter(theme, builtin));
    }
    // dates
    if is_on(group_index("dates").unwrap()) {
        list.push(date_highlighter(theme, builtin));
    }
    // ip addresses
    if is_on(group_index("ip-addresses").unwrap()) {
        list.push(ip_highlighter(theme, builtin));
    }
    // urls
    if is_on(group_index("urls").unwrap()) {
        list.push(url_highlighter(theme, builtin));
    }
    // paths
    if is_on(group_index("paths").unwrap()) {
        list.push(path_highlighter(theme));
    }
    // numbers
    if is_on(group_index("numbers").unwrap()) {
        list.push(number_highlighter(theme));
    }
    // key value pairs
    if is_on(group_index("key-value-pairs").unwrap()) {
        list.push(key_value_highlighter(theme));
    }
    // pointers
    if is_on(group_index("pointers").unwrap()) {
        list.push(pointer_highlighter(theme, builtin));
    }
    // processes
    if is_on(group_index("processes").unwrap()) {
        list.push(process_highlighter(theme));
    }
    // builtin keywords
    if !disable_builtin {
        for (words, style) in builtin_keywords() {
            if let Some(k) = keywords(&words, style) {
                list.push(k.highlighter());
            }
        }
    }
    // custom keywords from the configuration file
    for entry in theme.keywords() {
        if let Some(k) = keywords(&entry.words, entry.style) {
            list.push(k.highlighter());
        }
    }
    // custom keywords from the command line
    for (words, style) in cli_keywords {
        if let Some(k) = keywords(words, style.clone()) {
            list.push(k.highlighter());
        }
    }
    // quotes
    if is_on(group_index("quotes").unwrap()) {
        list.push(quote_highlighter(theme));
    }
    Highlighters { list }
}

/// The builtin keyword groups: log severities, booleans, nulls and REST verbs.
pub fn builtin_keywords() -> Vec<(Vec<String>, Style)> {
    vec![
        (vec!["ERROR".to_string()], Style::fg(Color::Red)),
        (vec!["WARN".to_string()], Style::fg(Color::Yellow)),
        (vec!["INFO".to_string()], Style::fg(Color::White)),
        (vec!["DEBUG".to_string()], Style::fg(Color::Green)),
        (vec!["TRACE".to_string()], Style { faint: true, ..Default::default() }),
        (vec!["SUCCESS".to_string()], Style::fg(Color::Green)),
        (
            vec!["true".to_string(), "false".to_string()],
            Style {
                italic: true,
                fg: Some(Color::Red),
                ..Default::default()
            },
        ),
        (
            vec!["null".to_string()],
            Style {
                italic: true,
                fg: Some(Color::Red),
                ..Default::default()
            },
        ),
        (
            vec!["GET".to_string()],
            Style {
                bg: Some(Color::Green),
                fg: Some(Color::Black),
                ..Default::default()
            },
        ),
        (
            vec!["POST".to_string()],
            Style {
                bg: Some(Color::Yellow),
                fg: Some(Color::Black),
                ..Default::default()
            },
        ),
        (
            vec!["PUT".to_string()],
            Style {
                bg: Some(Color::Magenta),
