// ------------------------------------------------------- highlighter set ----

/// All the highlighters in the order in which they are applied.
pub struct Highlighters {
    list: Vec<Highlighter>,
}

impl Highlighters {
    /// Render a single line of text.
    pub fn highlight(&self, line: &str) -> String {
        let mut pieces = vec![Piece::unstyled(line)];
        for h in &self.list {
            h.apply(&mut pieces);
        }
        let mut out = String::new();
        for piece in pieces {
            match &piece.style {
                Some(style) => {
                    let start = style.to_start();
                    if start.is_empty() {
                        out.push_str(&piece.text);
                    } else {
                        out.push_str(&start);
                        out.push_str(&piece.text);
