{"command": "cd /workspace && cat > src/cli.rs <<'EOF'
//! Command line parsing.
use clap::builder::{ArgAction, Arg, Command, StyledStr, NonZeroStringValueParser};
use clap::CommandFactory;
EOF
cat > src/main.rs <<'EOF'
//! tspin: a log file highlighter.
mod error;
mod highlighters;
mod hl;
mod ipv6;
mod less;
mod shlex;
mod tail;
mod theme;

use std::io::IsTerminal;
use std::path::PathBuf;

use clap::builder::NonZeroStringValueParser;
use clap::{Arg, ArgAction, Command, ValueParser};
use clap::CommandFactory as _;

use crate::error::{Result, TspinError};
use crate::hl::{build, builtin_keywords, Highlighters, GROUP_NAMES};
use crate::hl::Builtin;
use crate::theme::{Color, Style, Theme};

const VERSION: &str = "5.6.0";

/// Parse the command line arguments.
struct Cli {
    file: Option<String>,
    follow: bool,
    print: bool,
    config_path: Option<String>,
    exec: Option<String>,
    highlight: Vec<(Color, Vec<String>)>,
    enable: Option<Vec<usize>>,
    disable: Option<Vec<usize>>,
    disable_builtin: bool,
    pager: Option<String>,
}

fn command() -> Command {
    let group_names: Vec<String> = GROUP_NAMES.iter().map(|s| s.to_string()).collect();
    Command::new("tspin")
        .version(VERSION)
        .about("A log file highlighter")
        .arg(
            Arg::new("file")
                .value_name("FILE")
                .help("Filepath")
                .num_args(0..=1),
        )
        .arg(
            Arg::new("follow")
                .short('f')
                .long("follow")
                .action(ArgAction::SetTrue)
                .help("Follow the contents of a file"),
        )
        .arg(
            Arg::new("print")
                .short('p')
                .long("print")
                .action(ArgAction::SetTrue)
                .help("Print the output to stdout"),
        )
        .arg(
            Arg::new("config_path")
                .long("config-path")
                .value_name("CONFIG_PATH")
                .help("Provide a custom path to a configuration file"),
        )
        .arg(
            Arg::new("exec")
                .short('e')
                .long("exec")
                .alias("listen-command")
                .value_name("EXEC")
                .help("Run command and view the output in a pager"),
        )
        .arg(
            Arg::new("highlight")
                .long("highlight")
                .value_name("COLOR_WORD")
                .action(ArgAction::Append)
                .value_parser(ValueParser::new(highlight_parser))
                .help("Highlights in the form color:word1,word2"),
        )
        .arg(
            Arg::new("enable")
                .long("enable")
                .value_name("ENABLED_HIGHLIGHTERS")
                .value_parser(ValueParser::new(group_parser))
                .help("Enable specific highlighters"),
        )
        .arg(
            Arg::new("disable")
                .long("disable")
                .value_name("DISABLED_HIGHLIGHTERS")
                .value_parser(ValueParser::new(group_parser))
                .help("Disable specific highlighters"),
        )
        .arg(
            Arg::new("disable_builtin_keywords")
                .long("disable-builtin-keywords")
                .action(ArgAction::SetTrue)
                .help(
                    "Disable the highlighting of all builtin keyword groups (booleans, nulls, log severities and common REST verbs)",
                ),
        )
        .arg(
            Arg::new("pager")
                .long("pager")
                .value_name("PAGER")
                .env("TAILSPIN_PAGER")
                .help(
                    "Override the default pager command used by tspin. (e.g. `--pager=\"ov -f [FILE]\"`)",
                ),
        )
}

fn highlight_parser(cmd: &Command, arg: Option<&Arg>, value: &str) -> Result<(Color, Vec<String>), clap::Error> {
    let (color, words) = match value.split_once(':') {
        Some((c, w)) => (c, w),
        None => {
            return Err(clap::Error::raw(
                clap::ErrorKind::InvalidValue,
                format!("Expected format COLOR:word1,word2,... found `{}`", value),
            ))
        }
    };
    let color = match color {
        "red" => Color::Red,
        "green" => Color::Green,
        "yellow" => Color::Yellow,
        "blue" => Color::Blue,
        "magenta" => Color::Magenta,
        "cyan" => Color::Cyan,
        other => {
            return Err(clap::Error::raw(
                clap::ErrorKind::InvalidValue,
                format!("invalid variant: {}", other),
            ))
        }
    };
    let words: Vec<String> = words.split(',').filter(|w| !w.is_empty()).map(|w| w.to_string()).collect();
    Ok((color, words))
}

fn group_parser(cmd: &Command, arg: Option<&Arg>, value: &str) -> Result<Vec<usize>, clap::Error> {
    let mut res = Vec::new();
    for part in value.split(',') {
        match GROUP_NAMES.iter().position(|n| *n == part) {
            Some(i) => res.push(i),
            None => {
                return Err(clap::Error::raw(
                    clap::ErrorKind::InvalidValue,
                    format!("invalid value '{}'", part),
                ))
            }
        }
    }
    Ok(res)
}

fn parse_args() -> Result<Cli> {
    let mut cmd = command();
    let matches = match cmd.clone().try_get_matches_from(std::env::args_os()) {
        Ok(m) => m,
        Err(e) => {
            let _ = e.print();
            std::process::exit(e.exit_code());
        }
    };
    ...
}
EOF
echo ok"}

