fn highlight_parser(cmd: &Command, arg: Option<&Arg>, value: &str) -> Result<(Color, Vec<String>), clap::Error> {
    let (color, words) = match value.split_once(':') {
        Some((c, w)) => (c, w),
        None => {
            return Err(clap::Error::raw(
                clap::ErrorKind::InvalidValue,
                format!("Expected format COLOR:word1,word2,... found `{}`", value),
            ))
        }
    };
