{"command": "cd /workspace && cat >> src/main.rs <<'EOF'

fn load_theme(config_path: Option<&str>) -> Result<Theme> {
    let path: PathBuf = match config_path {
        Some(p) => {
            let path = PathBuf::from(p);
            if !path.exists() {
                return Err(TspinError::TomlNotFound);
            }
            path
        }
        None => {
            let dir = match std::env::var("XDG_CONFIG_HOME") {
                Ok(v) => PathBuf::from(v),
                Err(_) => {
                    let home = std::env::var("HOME")
                        .map_err(|e| TspinError::HomeEnvironment(e.to_string()))?;
                    PathBuf::from(home).join(".config")
                }
            };
            dir.join("tailspin").join("theme.toml")
        }
    };
    if !path.exists() {
        return Ok(Theme::default_theme());
    }
    let content = std::fs::read_to_string(&path).map_err(|e| {
        TspinError::TomlRead(
            "could not read the TOML file".to_string(),
            e,
        )
    })?;
    match toml::from_str::<Theme>(&content) {
        Ok(t) => Ok(merge_theme(t)),
        Err(e) => Err(TspinError::TomlParse(e.to_string())),
    }
}

/// Merge the parsed theme with the defaults so that unspecified entries keep
/// their default styling.
fn merge_theme(t: Theme) -> Theme {
    let mut out = Theme::default_theme();
    if t.dates.is_some() {
        out.dates = t.dates;
    }
    if t.numbers.is_some() {
        out.numbers = t.numbers;
    }
    if t.urls.is_some() {
        out.urls = t.urls;
    }
    if t.pointers.is_some() {
        out.pointers = t.pointers;
    }
    if t.paths.is_some() {
        out.paths = t.paths;
    }
    if t.quotes.is_some() {
        out.quotes = t.quotes;
    }
    if t.uuids.is_some() {
        out.uuids = t.uuids;
    }
    if t.processes.is_some() {
        out.processes = t.processes;
    }
    if t.json.is_some() {
        out.json = t.json;
    }
    if t.key_value_pairs.is_some() {
        out.key_value_pairs = t.key_value_pairs;
    }
    if t.keywords.is_some() {
        out.keywords = t.keywords;
    }
    out
}

fn main() {
    let cli = Cli::parse();
    match run(&cli) {
        Ok(()) => (),
        Err(e) => {
            crate::error::print_error(&e);
            std::process::exit(1);
        }
    }
}

fn run(cli: &Cli) -> Result<()> {
    if cli.enable.is_some() && cli.disable.is_some() {
        return Err(TspinError::BothEnableAndDisable);
    }
    let theme = load_theme(cli.config_path.as_deref())?;
    let builtin = Builtin::new();
    let cli_keywords: Vec<(Vec<String>, Style)> = cli
        .highlight
        .iter()
        .map(|c| (c.words.clone(), Style::fg(c.color.color())))
        .collect();
    let enabled = cli.enable.clone();
    let disabled = cli.disable.clone().unwrap_or_default();
    let hl = build(
        &theme,
        &builtin,
        enabled.as_deref(),
        &disabled,
        cli.disable_builtin_keywords,
        &cli_keywords,
    );
    let use_pager = !cli.print
        && (cli.file.is_some() || cli.exec.is_some())
        && std::io::stdout().is_terminal();
    if use_pager {
        let temp = crate::less::TempFile::new();
        if let Some(cmd) = &cli.exec {
            let child = crate::tail::spawn_command(cmd)?;
            crate::tail::follow_reader(child, &temp, &hl)?;
        } else if let Some(file) = &cli.file {
            check_file(file)?;
            crate::tail::follow_file(file, &temp, &hl)?;
        } else {
            crate::tail::follow_reader(std::io::stdin(), &temp, &hl)?;
        }
        crate::less::run_pager(
            cli.pager.as_deref().unwrap_or(crate::less::DEFAULT_PAGER),
            temp.path(),
        )
    } else {
        let mut out = String::new();
        if let Some(cmd) = &cli.exec {
            let mut child = crate::tail::spawn_command_print(cmd)?;
            let mut buf = String::new();
            use std::io::Read;
            let _ = child.stdout.read_to_string(&mut buf);
            for line in crate::tail::lines_of(&buf) {
                out.push_str(&crate::tail::highlight_line(&line, &hl));
            }
            let _ = child.wait();
        } else if let Some(file) = &cli.file {
            check_file(file)?;
            let content = std::fs::read_to_string(file)
