        && (cli.file.is_some() || cli.exec.is_some())
        && std::io::stdout().is_terminal();
    if use_pager {
        let temp = crate::less::TempFile::new();
        if let Some(cmd) = &cli.exec {
            let child = crate::tail::spawn_command(cmd)?;
            crate::tail::follow_reader(child, &temp, &hl)?;
        } else if let Some(file) = &cli.file {
            check_file(file)?;
            crate::tail::follow_file(file, &temp, &hl)?;
