//! Following a file or a command and feeding the pager.
use std::io::Read;
use std::process::{Child, Command, Stdio};
use std::time::Duration;

use crate::error::{Result, TspinError};
use crate::hl::Highlighters;
use crate::less::TempFile;

/// Sleep interval used while following.
pub const POLL_INTERVAL: Duration = Duration::from_millis(1);

/// Highlight a single line, including the trailing newline.
pub fn highlight_line(line: &str, hl: &Highlighters) -> String {
    let mut out = hl.highlight(line);
    out.push('\n');
    out
}

/// Split the text into the lines it contains, dropping the trailing newline.
pub fn lines_of(text: &str) -> Vec<String> {
    if text.is_empty() {
        return Vec::new();
    }
    let mut parts: Vec<&str> = text.split('\n').collect();
    if parts.last() == Some(&"") {
        parts.pop();
    }
    parts.iter().map(|s| s.to_string()).collect()
}

/// Spawn the command that should be followed.
pub fn spawn_command(cmd: &str, stdout_only: bool) -> Result<Child> {
    let full = format!("trap '' INT; {}", cmd);
    let mut command = Command::new("sh");
    command.arg("-c").arg(full);
    if stdout_only {
        command.stdout(Stdio::piped()).stderr(Stdio::inherit());
    } else {
        command.stdout(Stdio::piped());
    }
    match command.spawn() {
        Ok(child) => Ok(child),
        Err(e) => Err(TspinError::CommandRead(cmd.to_string(), e)),
    }
}

/// Follow a file, appending the highlighted lines to the temp file.
pub fn follow_file(path: &str, temp: &TempFile, hl: &Highlighters) -> Result<()> {
    std::thread::spawn(move || {
        let mut pos: u64 = 0;
        let mut partial = String::new();
        loop {
            match std::fs::File::open(path) {
                Ok(mut file) => {
                    use std::io::{Seek, SeekFrom};
                    let _ = file.seek(SeekFrom::Start(pos));
                    let mut buffer = Vec::new();
                    let _ = file.read_to_end(&mut buffer);
                    if !buffer.is_empty() {
                        pos += buffer.len() as u64;
                        partial.push_str(&String::from_utf_lossy(&buffer));
                        let (lines, consumed) = complete_lines(&partial);
                        partial.drain(..consumed);
                        let mut out = String::new();
                        for line in lines {
                            out.push_str(&highlight_line(&line, hl));
                        }
                        let _ = temp.append(&out);
                    }
                }
                Err(_) => {}
            }
            std::thread::sleep(POLL_INTERVAL);
        }
    });
    Ok(())
}

/// Read from a reader and append the highlighted lines to the temp file.
pub fn follow_reader(mut reader: impl Read + Send, temp: &TempFile, hl: &Highlighters) -> Result<()> {
    std::thread::spawn(move || {
        let mut pending: Vec<u8> = Vec::new();
        let mut buf = [0u8; 4096];
        loop {
            match reader.read(&mut buf) {
                Ok(0) => {
                    std::thread::sleep(POLL_INTERVAL);
                }
                Ok(n) => {
                    pending.extend_from_slice(&buf[..n]);
                    let text = String::from_utf_lossy(&pending).to_string();
                    let (lines, consumed) = complete_lines(&text);
                    pending.drain(..consumed);
                    let mut out = String::new();
                    for line in lines {
                        out.push_str(&highlight_line(&line, hl));
                    }
                    let _ = temp.append(&out);
                }
                Err(ref e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                Err(_) => {
                    std::thread::sleep(POLL_INTERVAL);
                }
            }
        }
    });
    Ok(())
}

/// Split the text into complete lines and the remaining partial line.
fn complete_lines(text: &str) -> (Vec<String>, usize) {
    let mut lines = Vec::new();
    let mut start = 0;
    let mut consumed = 0;
    for (i, c) in text.char_indices() {
        if c == '\n' {
            lines.push(text[start..i].to_string());
            consumed = i + 1;
            start = i + 1;
        }
    }
    (lines, consumed)
}
