{"command": "cd /workspace && cat > src/main.rs <<'EOF'
//! tspin: a log file highlighter.
mod error;
mod highlighters;
mod hl;
mod ipv6;
mod less;
mod shlex;
mod tail;
mod theme;

use std::ffi::OsStr;
use std::io::IsTerminal;
use std::path::PathBuf;

use clap::builder::{ArgAction, PossibleValue, PossibleValuesParser, TypedValueParser};
use clap::{Arg, Command, Error as ClapError};

use crate::error::{Result, TspinError};
use crate::hl::{build, Builtin, GROUP_NAMES};
use crate::theme::{Color, Style, Theme};

pub const VERSION: &str = "5.6.0";
pub const ABOUT: &str = "A log file highlighter";

/// A color chosen on the command line for a custom highlighter.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HighlightColor {
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
}

impl HighlightColor {
    fn color(&self) -> Color {
        match self {
            HighlightColor::Red => Color::Red,
            HighlightColor::Green => Color::Green,
            HighlightColor::Yellow => Color::Yellow,
            HighlightColor::Blue => Color::Blue,
            HighlightColor::Magenta => Color::Magenta,
            HighlightColor::Cyan => Color::Cyan,
        }
    }
}

/// A single `--highlight` argument: a color and the words to highlight.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ColorWord {
    pub color: HighlightColor,
    pub words: Vec<String>,
}

const HIGHLIGHT_COLORS: [&str; 6] = ["red", "green", "yellow", "blue", "magenta", "cyan"];

#[derive(Clone)]
struct HighlightParser;

impl TypedValueParser for HighlightParser {
    type Value = ColorWord;

    fn parse_ref(
        &self,
        _cmd: &Command,
        arg: Option<&Arg>,
        value: &OsStr,
    ) -> Result<ColorWord, ClapError> {
        let value = match value.to_str() {
            Some(v) => v,
            None => {
                return Err(ClapError::raw(
                    ClapErrorKind::InvalidUtf8,
                    "invalid utf-8",
                ))
            }
        };
        let arg_name = arg.map(|a| a.to_string()).unwrap_or_default();
        let (color, words) = match value.split_once(':') {
            Some((c, w)) => (c, w),
            None => {
                return Err(ClapError::raw(
                    ClapErrorKind::ValueValidation,
                    format!(
                        "invalid value '{}' for '{}': Expected format COLOR:word1,word2,... found `{}`",
                        value, arg_name, value
                    ),
                ))
            }
        };
        let color = match color {
            "red" => HighlightColor::Red,
            "green" => HighlightColor::Green,
            "yellow" => HighlightColor::Yellow,
            "blue" => HighlightColor::Blue,
            "magenta" => HighlightColor::Magenta,
            "cyan" => HighlightColor::Cyan,
            other => {
                return Err(ClapError::raw(
                    ClapErrorKind::ValueValidation,
                    format!(
                        "invalid value '{}' for '{}': invalid variant: {}",
                        value, arg_name, other
                    ),
                ))
            }
        };
        let words: Vec<String> = words
            .split(',')
            .filter(|w| !w.is_empty())
            .map(|w| w.to_string())
            .collect();
        Ok(ColorWord { color, words })
    }

    fn possible_values(&self) -> Option<Box<dyn Iterator<Item = PossibleValue> + '_>> {
        Some(Box::new(
            HIGHLIGHT_COLORS.iter().map(|v| PossibleValue::new(*v)),
        ))
    }
}

#[derive(Clone)]
struct GroupParser;

impl TypedValueParser for GroupParser {
    type Value = Vec<usize>;

    fn parse_ref(
        &self,
        cmd: &Command,
        arg: Option<&Arg>,
        value: &OsStr,
    ) -> Result<Vec<usize>, ClapError> {
        let value = match value.to_str() {
            Some(v) => v,
            None => {
                return Err(ClapError::raw(
                    ClapErrorKind::InvalidUtf8,
                    "invalid utf-8",
                ))
            }
        };
        let parser = PossibleValuesParser::new(GROUP_NAMES.iter().map(|s| s.to_string()));
        let mut res = Vec::new();
        for part in value.split(',') {
            let name = parser.parse_ref(cmd, arg, OsStr::new(part))?;
            let index = GROUP_NAMES.iter().position(|n| *n == name).unwrap();
            res.push(index);
        }
        Ok(res)
    }

    fn possible_values(&self) -> Option<Box<dyn Iterator<Item = PossibleValue> + '_>> {
        Some(Box::new(
            GROUP_NAMES.iter().map(|v| PossibleValue::new(*v)),
        ))
    }
}

/// The parsed command line.
struct Cli {
    file: Option<String>,
    follow: bool,
    print: bool,
    config_path: Option<String>,
    exec: Option<String>,
    highlight: Vec<ColorWord>,
    enable: Option<Vec<usize>>,
    disable: Option<Vec<usize>>,
    disable_builtin_keywords: bool,
    pager: Option<String>,
}

fn command() -> Command {
    Command::new("tspin")
        .version(VERSION)
        .about(ABOUT)
        .arg(
            Arg::new("file")
                .value_name("FILE")
                .num_args(0..=1)
                .help("Filepath"),
        )
        .arg(
            Arg::new("follow")
                .short('f')
                .long("follow")
                .action(ArgAction::SetTrue)
                .help("Follow the contents of a file"),
        )
        .arg(
            Arg::new("print")
                .short('p')
                .long("print")
                .action(ArgAction::SetTrue)
                .help("Print the output to stdout"),
        )
        .arg(
            Arg::new("config_path")
                .long("config-path")
                .value_name("CONFIG_PATH")
                .help("Provide a custom path to a configuration file"),
        )
        .arg(
            Arg::new("exec")
                .short('e')
                .long("exec")
                .alias("listen-command")
                .value_name("EXEC")
                .help("Run command and view the output in a pager"),
        )
        .arg(
            Arg::new("highlight")
                .long("highlight")
                .value_name("COLOR_WORD")
                .action(ArgAction::Append)
                .value_parser(HighlightParser)
                .help("Highlights in the form color:word1,word2"),
        )
        .arg(
            Arg::new("enable")
                .long("enable")
                .value_name("ENABLED_HIGHLIGHTERS")
                .value_parser(GroupParser)
                .help("Enable specific highlighters"),
        )
        .arg(
            Arg::new("disable")
                .long("disable")
                .value_name("DISABLED_HIGHLIGHTERS")
                .value_parser(GroupParser)
                .help("Disable specific highlighters"),
        )
        .arg(
            Arg::new("disable_builtin_keywords")
                .long("disable-builtin-keywords")
                .action(ArgAction::SetTrue)
                .help(
                    "Disable the highlighting of all builtin keyword groups (booleans, nulls, log severities and common REST verbs)",
                ),
        )
        .arg(
            Arg::new("pager")
                .long("pager")
                .value_name("PAGER")
                .env("TAILSPIN_PAGER")
                .help(
                    "Override the default pager command used by tspin. (e.g. `--pager=\"ov -f [FILE]\"`)",
                ),
        )
}

fn parse_args() -> Result<Cli> {
    let mut cmd = command();
    let matches = match cmd.clone().try_get_matches_from(std::env::args_os()) {
        Ok(m) => m,
        Err(e) => {
            let _ = e.print();
            std::process::exit(e.exit_code());
        }
    };
    Ok(Cli {
        file: matches.get_one::<String>("file").cloned(),
        follow: matches.get_flag("follow"),
        print: matches.get_flag("print"),
        config_path: matches.get_one::<String>("config_path").cloned(),
        exec: matches.get_one::<String>("exec").cloned(),
        highlight: matches
            .get_many::<ColorWord>("highlight")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        enable: matches.get_one::<Vec<usize>>("enable").cloned(),
        disable: matches.get_one::<Vec<usize>>("disable").cloned(),
        disable_builtin_keywords: matches.get_flag("disable_builtin_keywords"),
        pager: matches.get_one::<String>("pager").cloned(),
    })
}
